INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Zeichenkodierung immer alle Sprachen abdeckt?', 2, '[{"text": "Nein", "correct": true, "because": "Begrenzt auf bestimmte Zeichen"}, {"text": "Ja", "correct": false, "because": "Spezifische Teile"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Teil der Kodierung ist für westeuropäische Sprachen gedacht?', 3, '[{"text": "ISO-8859-1", "correct": true, "because": "Latin-1 für Westeuropa"}, {"text": "ISO-8859-5", "correct": false, "because": "Kyrillisch"}, {"text": "ISO-8859-15", "correct": false, "because": "Erweiterte Latin-1"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat eine Kodierung wie ISO-8859?', 5, '[{"text": "8-Bit Kodierung", "correct": true, "because": "256 Zeichen"}, {"text": "Regionale Zeichen", "correct": true, "because": "Sprachspezifisch"}, {"text": "ASCII-kompatibel", "correct": true, "because": "Erste 128 Zeichen"}, {"text": "Grafikdesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ISO-8859-1 ist Latin-1. b) ISO-8859-2 ist für asiatische Sprachen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "ISO-8859-2 ist für Osteuropa"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine Kodierung für Text wähle?', 4, '[{"text": "Zeichensatz", "correct": false, "because": "Definiert verfügbare Zeichen"}, {"text": "Region", "correct": false, "because": "Sprachspezifisch wichtig"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Kodierung wie ISO-8859-1 alle Zeichen abdeckt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nur 256 Zeichen"}, {"text": "Ja", "correct": false, "because": "Begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Teil unterstützt kyrillische Zeichen?', 3, '[{"text": "ISO-8859-5", "correct": true, "because": "Für kyrillische Sprachen"}, {"text": "ISO-8859-1", "correct": false, "because": "Latin-1"}, {"text": "ISO-8859-3", "correct": false, "because": "Südeuropa"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Kodierung wie ISO-8859-1?', 5, '[{"text": "Westeuropäische Zeichen", "correct": true, "because": "Sprachspezifisch"}, {"text": "Einfache Implementierung", "correct": true, "because": "8-Bit Standard"}, {"text": "ASCII-Kompatibilität", "correct": true, "because": "Erste 128 Zeichen"}, {"text": "Alle Sprachen", "correct": false, "because": "Begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) ISO-8859-15 das Eurozeichen hat und b) ISO-8859-1 es auch hat. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "ISO-8859-1 fehlt Euro"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um eine Kodierung wie ISO-8859 zu nutzen?', 4, '[{"text": "Textverarbeitung", "correct": false, "because": "Verwendet Kodierung"}, {"text": "Regionale Anpassung", "correct": false, "because": "Sprachspezifisch"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ISO-8859-1 dasselbe wie UTF-8?', 2, '[{"text": "Nein", "correct": true, "because": "UTF-8 ist variabel"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Kodierungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Teile unterstützen verschiedene Sprachen?', 4, '[{"text": "ISO-8859-2", "correct": true, "because": "Osteuropa"}, {"text": "ISO-8859-7", "correct": true, "because": "Griechisch"}, {"text": "ISO-8859-1", "correct": false, "because": "Nur Westeuropa"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Kodierung wie ISO-8859-1 veraltet ist. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "UTF-8 hat übernommen"}, {"text": "Nein", "correct": false, "because": "Noch in Verwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer regionalen Kodierung?', 3, '[{"text": "Sprachspezifische Zeichen", "correct": true, "because": "Regionale Anpassung"}, {"text": "Datenkompression", "correct": false, "because": "Anderer Zweck"}, {"text": "Designverbesserung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ISO-8859-3 ist für Südeuropa. b) ISO-8859-15 fehlt das Eurozeichen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "ISO-8859-15 hat Euro"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt ISO-8859-15 gegenüber ISO-8859-1?', 4, '[{"text": "Erweiterung mit Euro", "correct": true, "because": "Fügt Zeichen hinzu"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Anderer Zweck"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ISO-8859-5 lateinische Zeichen hat?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Kyrillisch"}, {"text": "Ja", "correct": false, "because": "Spezifisch kyrillisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Kodierung wie ISO-8859 nützlich?', 5, '[{"text": "Regionale Zeichen", "correct": true, "because": "Sprachspezifisch"}, {"text": "Einfache Nutzung", "correct": true, "because": "8-Bit Standard"}, {"text": "ASCII-Basis", "correct": true, "because": "Kompatibilität"}, {"text": "Alle Sprachen", "correct": false, "because": "Begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ISO-8859-1 für asiatische Sprachen?', 3, '[{"text": "Nein", "correct": true, "because": "Nur westeuropäisch"}, {"text": "Ja", "correct": false, "because": "Falscher Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zur Anwendung einer Kodierung?', 4, '[{"text": "Text in deutscher Sprache speichern", "correct": true, "because": "ISO-8859-1 passt"}, {"text": "Webseitenlayout erstellen", "correct": false, "because": "Designfokus"}, {"text": "Datenkompression", "correct": false, "because": "Anderer Zweck"}]');
